DROP TABLE IF EXISTS `bookings`;
CREATE TABLE `bookings`  (
  `ID` bigint NOT NULL AUTO_INCREMENT,
  `BOOKING_NO` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `BOOKING_STATUS` enum('ACCEPTED_BY_DRIVER','ARRIVED_AT_LAUNDRY','CANCELLED','CLOTHES_COLLECTED','COMPLETED','DRIVER_GOING_TO_CUSTOMER','DRYING','PAID_WAITING_DRIVER','PENDING_PAYMENT','READY_FOR_DELIVERY','RETURNING_TO_CUSTOMER','WASHING') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `COMPLETED_AT` datetime(6) NULL DEFAULT NULL,
  `CREATED_AT` datetime(6) NOT NULL,
  `CUSTOMER_COMMENT` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `CUSTOMER_RATING` int NULL DEFAULT NULL,
  `PICKUP_ADDRESS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `PICKUP_CITY` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `PICKUP_DATE_TIME` datetime(6) NULL DEFAULT NULL,
  `PICKUP_LATITUDE` decimal(38, 2) NULL DEFAULT NULL,
  `PICKUP_LONGITUDE` decimal(38, 2) NULL DEFAULT NULL,
  `PICKUP_POSTCODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `PICKUP_STATE` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `RATED_AT` datetime(6) NULL DEFAULT NULL,
  `SERVICE_SUMMARY` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `TOTAL_AMOUNT` decimal(38, 2) NOT NULL,
  `CUSTOMER_ID` bigint NOT NULL,
  `DRIVER_ID` bigint NULL DEFAULT NULL,
  `LAUNDRY_LOCATION_ID` bigint NULL DEFAULT NULL,
  `CUSTOMER_MESSAGES_SEEN_AT` datetime(6) NULL DEFAULT NULL,
  `DRIVER_MESSAGES_SEEN_AT` datetime(6) NULL DEFAULT NULL,
  `DELIVERY_FEE` decimal(38, 2) NOT NULL,
  `DELIVERY_PROOF_AT` datetime(6) NULL DEFAULT NULL,
  `DELIVERY_PROOF_IMAGE` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `LAUNDRY_FEE` decimal(38, 2) NOT NULL,
  `PICKUP_PROOF_AT` datetime(6) NULL DEFAULT NULL,
  `PICKUP_PROOF_IMAGE` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `SERVICE_FEE` decimal(38, 2) NOT NULL,
  `PUBLIC_ID` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UKhrpa81on5qd1ga8r9ortdllev`(`BOOKING_NO` ASC) USING BTREE,
  UNIQUE INDEX `UKnou24yvb6cdmy1erd6s0bekbd`(`PUBLIC_ID` ASC) USING BTREE,
  INDEX `FKdia7p5qc5r9ie29iel16042fh`(`CUSTOMER_ID` ASC) USING BTREE,
  INDEX `FKq1skwy7etiw0qi6ar6eoiimnj`(`DRIVER_ID` ASC) USING BTREE,
  INDEX `FK1onuhmpud4txtv12w6ggh1436`(`LAUNDRY_LOCATION_ID` ASC) USING BTREE,
  CONSTRAINT `FK1onuhmpud4txtv12w6ggh1436` FOREIGN KEY (`LAUNDRY_LOCATION_ID`) REFERENCES `laundry_locations` (`ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FKdia7p5qc5r9ie29iel16042fh` FOREIGN KEY (`CUSTOMER_ID`) REFERENCES `customers` (`ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FKq1skwy7etiw0qi6ar6eoiimnj` FOREIGN KEY (`DRIVER_ID`) REFERENCES `drivers` (`ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

